package com.verifi.loan;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Hiring screen. Do not edit this file.
 */
class LoanBookTest {
    private static final String PLATFORM = "platform";
    private static final String BORROWER = "borrower";
    private static final String STRANGER = "stranger";

    private LoanBook book;

    @BeforeEach
    void setUp() {
        book = new LoanBook(PLATFORM);
    }

    @Test
    void remainingOfReturnsOutstandingBalance() {
        long id = disburse(10_000);
        assertEquals(10_000, book.remainingOf(id));
    }

    @Test
    void remainingOfRejectsAMissingLoan() {
        LoanBook.LoanException error = assertThrows(LoanBook.LoanException.class, () -> book.remainingOf(99));
        assertEquals("LOAN_NOT_FOUND", error.code());
    }

    @Test
    void borrowerPaymentReducesRemaining() {
        long id = disburse(10_000);
        book.recordPayment(BORROWER, id, 4_000);
        assertEquals(6_000, book.remainingOf(id));
        assertEquals(LoanBook.Status.DISBURSED, book.get(id).status());
    }

    @Test
    void platformCanRecordAPayment() {
        long id = disburse(10_000);
        book.recordPayment(PLATFORM, id, 1_000);
        assertEquals(9_000, book.remainingOf(id));
    }

    @Test
    void finalPaymentMarksTheLoanRepaid() {
        long id = disburse(10_000);
        book.recordPayment(BORROWER, id, 10_000);
        assertEquals(0, book.remainingOf(id));
        assertEquals(LoanBook.Status.REPAID, book.get(id).status());
    }

    @Test
    void strangerCannotPay() {
        long id = disburse(10_000);
        LoanBook.LoanException error = assertThrows(LoanBook.LoanException.class, () -> book.recordPayment(STRANGER, id, 100));
        assertEquals("UNAUTHORIZED", error.code());
    }

    @Test
    void rejectsZeroAndOverpayment() {
        long id = disburse(10_000);
        assertEquals("INVALID_AMOUNT", assertThrows(LoanBook.LoanException.class, () -> book.recordPayment(BORROWER, id, 0)).code());
        assertEquals("INVALID_AMOUNT", assertThrows(LoanBook.LoanException.class, () -> book.recordPayment(BORROWER, id, 10_001)).code());
    }

    @Test
    void rejectsPaymentBeforeDisbursal() {
        LoanBook.Loan created = book.create(PLATFORM, BORROWER, 5_000);
        book.approve(PLATFORM, created.id());
        LoanBook.LoanException error = assertThrows(LoanBook.LoanException.class, () -> book.recordPayment(BORROWER, created.id(), 100));
        assertEquals("INVALID_STATUS", error.code());
    }

    @Test
    void defaultsADisbursedLoan() {
        long id = disburse(5_000);
        book.markDefaulted(PLATFORM, id);
        assertEquals(LoanBook.Status.DEFAULTED, book.get(id).status());
    }

    @Test
    void cannotDefaultAnApprovedLoan() {
        LoanBook.Loan created = book.create(PLATFORM, BORROWER, 5_000);
        book.approve(PLATFORM, created.id());
        LoanBook.LoanException error = assertThrows(LoanBook.LoanException.class, () -> book.markDefaulted(PLATFORM, created.id()));
        assertEquals("INVALID_STATUS", error.code());
    }

    @Test
    void cannotDefaultARepaidLoan() {
        long id = disburse(5_000);
        book.recordPayment(BORROWER, id, 5_000);
        LoanBook.LoanException error = assertThrows(LoanBook.LoanException.class, () -> book.markDefaulted(PLATFORM, id));
        assertEquals("INVALID_STATUS", error.code());
    }

    private long disburse(long amountCents) {
        LoanBook.Loan loan = book.create(PLATFORM, BORROWER, amountCents);
        book.approve(PLATFORM, loan.id());
        book.disburse(PLATFORM, loan.id());
        return loan.id();
    }
}
